window.READING_REVIEW_DATA = {"items":[{"id":"babies-3d6a6664cf","term":"assignment","type":"word","sourceOrder":1,"zh":"作业","pos":"n.","ipa":"əˈsaɪnmənt","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"assign（布置任务）＋-ment（名词后缀）","tip":"布置下来的任务就是作业；不是随意分派一个号码。","family":"assign 布置；assignment 作业"},"examples":[{"en":"So Daniel, shall we compare a few ideas for our assignment on how babies and children learn?","zh":"那么，Daniel，我们来比较一下关于婴幼儿如何学习这份作业的几个想法，好吗？","source":"original","number":3},{"en":"Then I also thought I'd write about the present research in my assignment.","zh":"另外，我还想在作业里写写关于礼物的研究。","source":"original","number":24}]},{"id":"babies-a2a7589ae1","term":"vocabulary","type":"word","sourceOrder":2,"zh":"词汇","pos":"n.","ipa":"vəˈkæbjələri","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"The baby watches a short film with some basic vocabulary, maths, and science, and they learn as they watch.","zh":"婴儿观看包含基础词汇、数学和科学知识的短片，并在观看时学习。","source":"original","number":9}]},{"id":"babies-540201f3ce","term":"attention","type":"word","sourceOrder":3,"zh":"注意力","pos":"n.","ipa":"əˈtenʃən","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Certainly, babies will pay attention to videos for long periods of time.","zh":"当然，婴儿确实会长时间关注视频。","source":"original","number":11}]},{"id":"babies-e02f092ae9","term":"research","type":"word","sourceOrder":4,"zh":"研究","pos":"n.","ipa":"rɪˈsɜːtʃ","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Yeah, but there's been research to show that babies don't learn effectively from screens.","zh":"是的，但已有研究表明，婴儿无法有效地通过屏幕学习。","source":"original","number":12},{"en":"Then I also thought I'd write about the present research in my assignment.","zh":"另外，我还想在作业里写写关于礼物的研究。","source":"original","number":24},{"en":"I read a bit about the present research.","zh":"我也读过一点关于礼物的研究。","source":"original","number":26}]},{"id":"babies-93937eeb58","term":"effectively","type":"word","sourceOrder":5,"zh":"有效地","pos":"adv.","ipa":"ɪˈfektɪvli","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Yeah, but there's been research to show that babies don't learn effectively from screens.","zh":"是的，但已有研究表明，婴儿无法有效地通过屏幕学习。","source":"original","number":12}]},{"id":"babies-b93fc158a7","term":"interact","type":"word","sourceOrder":6,"zh":"互动","pos":"v.","ipa":"ˌɪntərˈækt","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"inter-（相互）＋act（行动）","tip":"彼此回应、一起行动，就是互动。","family":"interaction 互动；interactive 互动的"},"examples":[{"en":"Actually, they learn by interacting with their parents and other caregivers.","zh":"实际上，他们通过与父母及其他照顾者互动来学习。","source":"original","number":13}]},{"id":"babies-90c07d80e3","term":"caregiver","type":"word","sourceOrder":7,"zh":"照顾者","pos":"n.","ipa":"ˈkeəˌɡɪvə","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"care（照顾）＋giver（给予者）","tip":"提供照顾的人；本篇主要指父母及其他照顾者。","family":"care 照顾；caregiving 照护"},"examples":[{"en":"Actually, they learn by interacting with their parents and other caregivers.","zh":"实际上，他们通过与父母及其他照顾者互动来学习。","source":"original","number":13},{"en":"In her experiment, babies were given toys to play with, and their caregivers sometimes repeated the same movements as the baby and sometimes did something different.","zh":"在她的实验中，婴儿得到玩具进行玩耍；照顾者有时重复婴儿做的动作，有时做不同的动作。","source":"original","number":73},{"en":"The results showed that babies were happiest when parents or caregivers imitated their behavior.","zh":"结果显示，当父母或照顾者模仿他们的行为时，婴儿最开心。","source":"original","number":75}]},{"id":"babies-e047eb1a4b","term":"approach","type":"word","sourceOrder":8,"zh":"方法","pos":"n.","ipa":"əˈprəʊtʃ","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"That's the best approach.","zh":"这是最好的方式。","source":"original","number":14}]},{"id":"babies-114917e2f1","term":"issue","type":"word","sourceOrder":9,"zh":"问题","pos":"n.","ipa":"ˈɪʃuː","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Another issue with learning videos is that babies ought to have playtime.","zh":"学习视频的另一个问题是，婴儿应该有玩耍的时间。","source":"original","number":17}]},{"id":"babies-108c4e0fc3","term":"playtime","type":"word","sourceOrder":10,"zh":"玩耍时间","pos":"n.","ipa":"ˈpleɪtaɪm","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Another issue with learning videos is that babies ought to have playtime.","zh":"学习视频的另一个问题是，婴儿应该有玩耍的时间。","source":"original","number":17}]},{"id":"babies-bc0272627c","term":"necessarily","type":"word","sourceOrder":11,"zh":"必然地","pos":"adv.","ipa":"ˌnesəˈserəli","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Not necessarily.","zh":"不一定。","source":"original","number":19}]},{"id":"babies-a75c5e7960","term":"investigate","type":"word","sourceOrder":12,"zh":"探索；调查","pos":"v.","ipa":"ɪnˈvestɪɡeɪt","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"investigate → investigation（调查）","tip":"探索周围环境以发现信息；动作与过程名词一起记。","family":"investigation 调查；investigator 调查者"},"examples":[{"en":"But what's important is that they investigate their own environment.","zh":"但重要的是，他们要探索自己周围的环境。","source":"original","number":21}]},{"id":"babies-f2762b9d74","term":"environment","type":"word","sourceOrder":13,"zh":"周围环境","pos":"n.","ipa":"ɪnˈvaɪrənmənt","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"But what's important is that they investigate their own environment.","zh":"但重要的是，他们要探索自己周围的环境。","source":"original","number":21}]},{"id":"babies-5269462f14","term":"examine","type":"word","sourceOrder":14,"zh":"仔细察看","pos":"v.","ipa":"ɪɡˈzæmɪn","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"They should examine the objects around them and experiment, so they discover information for themselves, and they don't get that sitting in front of a film.","zh":"他们应该观察周围的物体并动手尝试，从而自己发现信息；而坐在屏幕前看影片无法获得这样的体验。","source":"original","number":22}]},{"id":"babies-055656f60d","term":"object","type":"word","sourceOrder":15,"zh":"物体","pos":"n.","ipa":"ˈɒbdʒɪkt","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"They should examine the objects around them and experiment, so they discover information for themselves, and they don't get that sitting in front of a film.","zh":"他们应该观察周围的物体并动手尝试，从而自己发现信息；而坐在屏幕前看影片无法获得这样的体验。","source":"original","number":22}]},{"id":"babies-924d2df85d","term":"experiment","type":"word","sourceOrder":16,"zh":"实验；尝试","pos":"n./v.","ipa":"ɪkˈsperɪmənt","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"They should examine the objects around them and experiment, so they discover information for themselves, and they don't get that sitting in front of a film.","zh":"他们应该观察周围的物体并动手尝试，从而自己发现信息；而坐在屏幕前看影片无法获得这样的体验。","source":"original","number":22},{"en":"There was a really interesting bilingual experiment in Spain.","zh":"西班牙曾进行过一项非常有趣的双语实验。","source":"original","number":46},{"en":"So because of that, the experiment was standardized across all the schools.","zh":"因此，实验在所有学校都遵循统一标准。","source":"original","number":51}]},{"id":"babies-6ca4395c38","term":"present","type":"word","sourceOrder":17,"zh":"礼物","pos":"n.","ipa":"ˈprezənt","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Then I also thought I'd write about the present research in my assignment.","zh":"另外，我还想在作业里写写关于礼物的研究。","source":"original","number":24},{"en":"I read a bit about the present research.","zh":"我也读过一点关于礼物的研究。","source":"original","number":26},{"en":"When you give a baby a present or gift, some of them are more interested in the wrapping paper than the present itself.","zh":"当你送给婴儿一份礼物时，有些婴儿对包装纸的兴趣比礼物本身更大。","source":"original","number":28}]},{"id":"babies-13c3b99968","term":"wrapping","type":"word","sourceOrder":18,"zh":"包装材料","pos":"n.","ipa":"ˈræpɪŋ","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"When you give a baby a present or gift, some of them are more interested in the wrapping paper than the present itself.","zh":"当你送给婴儿一份礼物时，有些婴儿对包装纸的兴趣比礼物本身更大。","source":"original","number":28},{"en":"So we shouldn't stop wrapping up babies' presents.","zh":"所以我们不应该停止给婴儿的礼物包装起来。","source":"original","number":43}]},{"id":"babies-6f4db2f33a","term":"prefer","type":"word","sourceOrder":19,"zh":"更喜欢","pos":"v.","ipa":"prɪˈfɜː","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"The research shows that pretty much every baby prefers the paper to the present, whether male or female.","zh":"研究显示，几乎每个婴儿都更喜欢包装纸，而不是礼物，无论男女。","source":"original","number":30}]},{"id":"babies-a6832910af","term":"characteristic","type":"word","sourceOrder":20,"zh":"特征","pos":"n.","ipa":"ˌkærəktəˈrɪstɪk","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"character（特征、性格）与 characteristic 同词族","tip":"某种人或事物的典型特点；本句作名词。","family":"character 特征；characteristically 典型地"},"examples":[{"en":"It's just a human characteristic.","zh":"这只是人类的一种普遍特征。","source":"original","number":31}]},{"id":"babies-344cb591dd","term":"exception","type":"word","sourceOrder":21,"zh":"例外","pos":"n.","ipa":"ɪkˈsepʃən","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"I thought there'd be more exceptions.","zh":"我原以为会有更多例外。","source":"original","number":33}]},{"id":"babies-92b88096ba","term":"ribbon","type":"word","sourceOrder":22,"zh":"丝带","pos":"n.","ipa":"ˈrɪbən","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"It seems that playing with the paper or ribbons or box stimulates the baby's senses.","zh":"看来，玩包装纸、丝带或盒子能刺激婴儿的感官。","source":"original","number":35},{"en":"They touch everything, climb into the box, put the ribbon into their mouths.","zh":"他们会摸各种东西、爬进盒子里，还会把丝带放进嘴里。","source":"original","number":36}]},{"id":"babies-3a91cbc995","term":"stimulate","type":"word","sourceOrder":23,"zh":"刺激；激发","pos":"v.","ipa":"ˈstɪmjuleɪt","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"stimulate → stimulation（刺激）","tip":"刺激感官 senses 帮助探索；与 simulate（模拟）区分。","family":"stimulation 刺激；stimulus 刺激物"},"examples":[{"en":"It seems that playing with the paper or ribbons or box stimulates the baby's senses.","zh":"看来，玩包装纸、丝带或盒子能刺激婴儿的感官。","source":"original","number":35},{"en":"And brain scans have shown that sight, sound, touch, smell, and taste are all stimulated in this way.","zh":"脑部扫描表明，视觉、听觉、触觉、嗅觉和味觉都会以这种方式受到刺激。","source":"original","number":37}]},{"id":"babies-775ae943ce","term":"sense","type":"word","sourceOrder":24,"zh":"感官","pos":"n.","ipa":"sens","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"It seems that playing with the paper or ribbons or box stimulates the baby's senses.","zh":"看来，玩包装纸、丝带或盒子能刺激婴儿的感官。","source":"original","number":35},{"en":"In a simple sense, they seem to know the function of nouns and verbs, and the researchers believe this is linked to the way they learn the meaning of new words.","zh":"简单来说，他们似乎知道名词和动词的作用；研究者认为，这与他们学习新词含义的方式有关。","source":"original","number":99}]},{"id":"babies-efecab8cb7","term":"scan","type":"word","sourceOrder":25,"zh":"扫描","pos":"n.","ipa":"skæn","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"And brain scans have shown that sight, sound, touch, smell, and taste are all stimulated in this way.","zh":"脑部扫描表明，视觉、听觉、触觉、嗅觉和味觉都会以这种方式受到刺激。","source":"original","number":37}]},{"id":"babies-3fa26a60aa","term":"specific","type":"word","sourceOrder":26,"zh":"具体的","pos":"adj.","ipa":"spəˈsɪfɪk","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"It's amazing the research has produced so much specific information just from studying presents.","zh":"令人惊讶的是，研究者仅通过研究礼物就获得了如此多的具体信息。","source":"original","number":38}]},{"id":"babies-7c70fd936e","term":"aspect","type":"word","sourceOrder":27,"zh":"方面","pos":"n.","ipa":"ˈæspekt","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"The results cover so many different aspects of baby behavior.","zh":"这些结果涉及婴儿行为的很多不同方面。","source":"original","number":40}]},{"id":"babies-e0d9030980","term":"behavior","type":"word","sourceOrder":28,"zh":"行为","pos":"n.","ipa":"bɪˈheɪvjə","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"The results cover so many different aspects of baby behavior.","zh":"这些结果涉及婴儿行为的很多不同方面。","source":"original","number":40},{"en":"The results showed that babies were happiest when parents or caregivers imitated their behavior.","zh":"结果显示，当父母或照顾者模仿他们的行为时，婴儿最开心。","source":"original","number":75}]},{"id":"babies-9a7156cdd5","term":"bilingual","type":"word","sourceOrder":29,"zh":"双语的","pos":"adj.","ipa":"baɪˈlɪŋɡwəl","stars":5,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"bi-（二）＋lingual（语言的）","tip":"两种语言，就是双语；bi- 还见于 bicycle 两轮车。","family":"bilingualism 双语能力；monolingual 单语的"},"examples":[{"en":"There was a really interesting bilingual experiment in Spain.","zh":"西班牙曾进行过一项非常有趣的双语实验。","source":"original","number":46}]},{"id":"babies-57084d1c49","term":"preschool","type":"word","sourceOrder":30,"zh":"学前教育机构","pos":"n.","ipa":"ˈpriːskuːl","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"pre-（在……之前）＋school（学校）","tip":"正式入学之前的教育机构。","family":"preschooler 学龄前儿童；school 学校"},"examples":[{"en":"They tried teaching English to a group of two hundred and eighty Spanish children in different preschools.","zh":"他们尝试在不同幼儿园里教280名西班牙儿童英语。","source":"original","number":47}]},{"id":"babies-79cf9e522d","term":"subject","type":"word","sourceOrder":31,"zh":"研究对象；受试者","pos":"n.","ipa":"ˈsʌbdʒɪkt","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"So the research subjects were in different schools?","zh":"所以实验对象来自不同学校？","source":"original","number":48},{"en":"The subjects were aged between seven months and three years old, and the children were given a one-hour English lesson for eighteen weeks.","zh":"受试儿童年龄介于7个月到3岁之间，连续18周接受每次一小时的英语课。","source":"original","number":55}]},{"id":"babies-0e8b8837ce","term":"deliberately","type":"word","sourceOrder":32,"zh":"有意地","pos":"adv.","ipa":"dɪˈlɪbərətli","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Yes, but the researchers deliberately selected teachers who all had the same education.","zh":"是的，但研究人员有意选择了教育背景相同的教师。","source":"original","number":49}]},{"id":"babies-144473221f","term":"education","type":"word","sourceOrder":33,"zh":"教育","pos":"n.","ipa":"ˌedʒuˈkeɪʃən","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Yes, but the researchers deliberately selected teachers who all had the same education.","zh":"是的，但研究人员有意选择了教育背景相同的教师。","source":"original","number":49}]},{"id":"babies-9caa808438","term":"interaction","type":"word","sourceOrder":34,"zh":"互动","pos":"n.","ipa":"ˌɪntərˈækʃən","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"interact（互动）＋-ion（名词后缀）","tip":"social interaction 是社交互动；别只听到 action 就忽略 inter-。","family":"interact 互动；interactive 互动的"},"examples":[{"en":"They had been trained to use a style that focused on play and social interaction.","zh":"这些教师此前都接受过培训，采用侧重游戏与社交互动的教学方式。","source":"original","number":50}]},{"id":"babies-635dc385a3","term":"standardized","type":"word","sourceOrder":35,"zh":"标准化的","pos":"adj.","ipa":"ˈstændədaɪzd","stars":5,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"standard（标准）＋-ize（使成为）＋-d","tip":"把各学校教学条件统一；英式常写 standardised。","family":"standard 标准；standardisation 标准化"},"examples":[{"en":"So because of that, the experiment was standardized across all the schools.","zh":"因此，实验在所有学校都遵循统一标准。","source":"original","number":51}]},{"id":"babies-95d604a584","term":"average","type":"word","sourceOrder":36,"zh":"平均数","pos":"n.","ipa":"ˈævərɪdʒ","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"But at the end of the experiment, each child could produce an average of seventy-four English words or phrases.","zh":"但在实验结束时，每名儿童平均能说出74个英语单词或短语。","source":"original","number":58}]},{"id":"babies-9ff3c72898","term":"follow-up","type":"word","sourceOrder":37,"zh":"后续的","pos":"adj.","ipa":"ˈfɒləʊ ʌp","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Well, follow-up testing showed that the classes had a long-term benefit.","zh":"嗯，后续测试显示，这些课程具有长期益处。","source":"original","number":60}]},{"id":"babies-2840e2c6d0","term":"benefit","type":"word","sourceOrder":38,"zh":"益处","pos":"n.","ipa":"ˈbenɪfɪt","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Well, follow-up testing showed that the classes had a long-term benefit.","zh":"嗯，后续测试显示，这些课程具有长期益处。","source":"original","number":60}]},{"id":"babies-cf78527eb7","term":"remarkable","type":"word","sourceOrder":39,"zh":"非凡的；引人注目的","pos":"adj.","ipa":"rɪˈmɑːkəbl","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Wow, that's remarkable, especially considering some of the children were so young.","zh":"哇，这很了不起，尤其考虑到一些孩子年龄那么小。","source":"original","number":62}]},{"id":"babies-be885c673d","term":"movement","type":"word","sourceOrder":40,"zh":"动作","pos":"n.","ipa":"ˈmuːvmənt","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"In her experiment, babies were given toys to play with, and their caregivers sometimes repeated the same movements as the baby and sometimes did something different.","zh":"在她的实验中，婴儿得到玩具进行玩耍；照顾者有时重复婴儿做的动作，有时做不同的动作。","source":"original","number":73}]},{"id":"babies-61b8df9805","term":"monitor","type":"word","sourceOrder":41,"zh":"监测","pos":"v.","ipa":"ˈmɒnɪtə","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"And Dr. Pritchard monitored the babies' electrical brain activity.","zh":"Pritchard 博士还监测了婴儿大脑的电活动。","source":"original","number":74}]},{"id":"babies-21818be54c","term":"electrical","type":"word","sourceOrder":42,"zh":"电的","pos":"adj.","ipa":"ɪˈlektrɪkəl","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"And Dr. Pritchard monitored the babies' electrical brain activity.","zh":"Pritchard 博士还监测了婴儿大脑的电活动。","source":"original","number":74}]},{"id":"babies-65506366df","term":"imitate","type":"word","sourceOrder":43,"zh":"模仿","pos":"v.","ipa":"ˈɪmɪteɪt","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"imitate → imitation（模仿）","tip":"照着婴儿动作做，形成模仿 imitation。","family":"imitation 模仿；imitative 模仿的"},"examples":[{"en":"The results showed that babies were happiest when parents or caregivers imitated their behavior.","zh":"结果显示，当父母或照顾者模仿他们的行为时，婴儿最开心。","source":"original","number":75}]},{"id":"babies-e88c1ff8e4","term":"assistance","type":"word","sourceOrder":44,"zh":"帮助","pos":"n.","ipa":"əˈsɪstəns","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"assist（帮助）＋-ance","tip":"give someone assistance 等于 give someone help。","family":"assist 帮助；assistant 助手"},"examples":[{"en":"They wanted to give someone assistance if they could, if they thought someone else had a problem.","zh":"如果可以，而且他们认为别人遇到了困难，他们就愿意帮助对方。","source":"original","number":84}]},{"id":"babies-e94dc5a155","term":"isolation","type":"word","sourceOrder":45,"zh":"孤立；独自的状态","pos":"n.","ipa":"ˌaɪsəˈleɪʃən","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"派生构词","parts":"isolate（使隔离）去 e，加 -ion → isolation。","tip":"与某些人群保持距离 → 相对隔离；不自动等于主观孤独。","family":"isolate v.；isolated 隔离的"},"examples":[{"en":"So I think that shows how babies are more likely to learn by working with caregivers and teachers rather than in isolation.","zh":"所以我认为，这说明婴幼儿与照顾者、教师一起活动，比独自学习更有可能学到东西。","source":"original","number":85}]},{"id":"babies-a5975d4569","term":"linguist","type":"word","sourceOrder":46,"zh":"语言学家","pos":"n.","ipa":"ˈlɪŋɡwɪst","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"lingu-（语言）＋-ist（从事者）","tip":"研究语言的专家；与 bilingual 的语言词族联想。","family":"linguistics 语言学；linguistic 语言的"},"examples":[{"en":"Is he a linguist?","zh":"他是一位语言学家吗？","source":"original","number":87}]},{"id":"babies-5bc5c08048","term":"button","type":"word","sourceOrder":47,"zh":"按钮","pos":"n.","ipa":"ˈbʌtən","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"Professor Michelson did a study where babies had to push buttons.","zh":"Michelson 教授做过一项实验，在实验中婴儿需要按按钮。","source":"original","number":89},{"en":"Some buttons switched on a light, and some didn't.","zh":"有些按钮能打开灯，而有些不能。","source":"original","number":90},{"en":"And after a little experimentation, the babies nearly always pushed a button that switched on a light.","zh":"经过一点尝试后，婴儿几乎总是选择能够打开灯的按钮。","source":"original","number":91}]},{"id":"babies-214fef129a","term":"recognize","type":"word","sourceOrder":48,"zh":"意识到；认识到","pos":"v.","ipa":"ˈrekəɡnaɪz","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"He believes they recognized that a certain thing would happen as a result of a certain action.","zh":"他认为婴儿意识到，某一特定动作会导致某个特定结果。","source":"original","number":94}]},{"id":"babies-235006140d","term":"implication","type":"word","sourceOrder":49,"zh":"启示；影响","pos":"n.","ipa":"ˌɪmplɪˈkeɪʃən","stars":4,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","memory":{"method":"构词／词族／搭配联想","parts":"implicate 对应名词 implication；用固定搭配记","tip":"have implications for 指对某方面有影响或启示；本文不是指牵涉罪行。","family":"implications for learning 对学习的启示；imply 暗示"},"examples":[{"en":"So maybe that has implications for learning.","zh":"所以这或许对学习研究具有启示意义。","source":"original","number":95}]},{"id":"babies-e851e8c1ea","term":"structure","type":"word","sourceOrder":50,"zh":"组织；构成","pos":"v.","ipa":"ˈstrʌktʃə","stars":3,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"This showed that babies as young as sixteen months have some knowledge of how language is structured.","zh":"这表明，甚至只有16个月大的婴儿也对语言的结构有所了解。","source":"original","number":98}]},{"id":"babies-7e77c7daa8","term":"function","type":"word","sourceOrder":51,"zh":"功能","pos":"n.","ipa":"ˈfʌŋkʃən","stars":2,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"In a simple sense, they seem to know the function of nouns and verbs, and the researchers believe this is linked to the way they learn the meaning of new words.","zh":"简单来说，他们似乎知道名词和动词的作用；研究者认为，这与他们学习新词含义的方式有关。","source":"original","number":99}]},{"id":"babies-be32af81d5","term":"noun","type":"word","sourceOrder":52,"zh":"名词","pos":"n.","ipa":"naʊn","stars":1,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"In a simple sense, they seem to know the function of nouns and verbs, and the researchers believe this is linked to the way they learn the meaning of new words.","zh":"简单来说，他们似乎知道名词和动词的作用；研究者认为，这与他们学习新词含义的方式有关。","source":"original","number":99}]},{"id":"babies-80204edac6","term":"verb","type":"word","sourceOrder":53,"zh":"动词","pos":"n.","ipa":"vɜːb","stars":1,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"In a simple sense, they seem to know the function of nouns and verbs, and the researchers believe this is linked to the way they learn the meaning of new words.","zh":"简单来说，他们似乎知道名词和动词的作用；研究者认为，这与他们学习新词含义的方式有关。","source":"original","number":99}]},{"id":"babies-3e268fae8d","term":"meaning","type":"word","sourceOrder":54,"zh":"含义","pos":"n.","ipa":"ˈmiːnɪŋ","stars":1,"note":"词义按本篇学习研究语境理解。","paragraph":"听力原文","examples":[{"en":"In a simple sense, they seem to know the function of nouns and verbs, and the researchers believe this is linked to the way they learn the meaning of new words.","zh":"简单来说，他们似乎知道名词和动词的作用；研究者认为，这与他们学习新词含义的方式有关。","source":"original","number":99}]},{"id":"babies-a8f44cf6a7","term":"pay attention to","type":"phrase","sourceOrder":55,"zh":"关注","pos":"搭配／句型","ipa":"peɪ əˈtenʃən tə","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Certainly, babies will pay attention to videos for long periods of time.","zh":"当然，婴儿确实会长时间关注视频。","source":"original","number":11}]},{"id":"babies-26c5800c73","term":"for long periods of time","type":"phrase","sourceOrder":56,"zh":"持续很长时间","pos":"搭配／句型","ipa":"fə lɒŋ ˈpɪəriədz əv taɪm","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Certainly, babies will pay attention to videos for long periods of time.","zh":"当然，婴儿确实会长时间关注视频。","source":"original","number":11}]},{"id":"babies-c7baf9efab","term":"learn effectively from screens","type":"phrase","sourceOrder":57,"zh":"有效地通过屏幕学习","pos":"搭配／句型","ipa":"lɜːn ɪˈfektɪvli frəm skriːnz","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Yeah, but there's been research to show that babies don't learn effectively from screens.","zh":"是的，但已有研究表明，婴儿无法有效地通过屏幕学习。","source":"original","number":12}]},{"id":"babies-b9e801df9c","term":"interact with","type":"phrase","sourceOrder":58,"zh":"与……互动","pos":"搭配／句型","ipa":"ˌɪntərˈækt wɪð","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Actually, they learn by interacting with their parents and other caregivers.","zh":"实际上，他们通过与父母及其他照顾者互动来学习。","source":"original","number":13}]},{"id":"babies-4f15346d52","term":"ought to","type":"phrase","sourceOrder":59,"zh":"应该","pos":"搭配／句型","ipa":"ɔːt tə","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Another issue with learning videos is that babies ought to have playtime.","zh":"学习视频的另一个问题是，婴儿应该有玩耍的时间。","source":"original","number":17}]},{"id":"babies-cfd42ba0e3","term":"not necessarily","type":"phrase","sourceOrder":60,"zh":"不一定","pos":"搭配／句型","ipa":"nɒt ˌnesəˈserəli","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Not necessarily.","zh":"不一定。","source":"original","number":19}]},{"id":"babies-44f24eaa84","term":"investigate their own environment","type":"phrase","sourceOrder":61,"zh":"探索自己的环境","pos":"搭配／句型","ipa":"ɪnˈvestɪɡeɪt ðeə əʊn ɪnˈvaɪrənmənt","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"But what's important is that they investigate their own environment.","zh":"但重要的是，他们要探索自己周围的环境。","source":"original","number":21}]},{"id":"babies-2c9d52bb2c","term":"discover information for themselves","type":"phrase","sourceOrder":62,"zh":"自己探索并发现信息","pos":"搭配／句型","ipa":"dɪˈskʌvə ˌɪnfəˈmeɪʃn fə ðəmˈselvz","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"They should examine the objects around them and experiment, so they discover information for themselves, and they don't get that sitting in front of a film.","zh":"他们应该观察周围的物体并动手尝试，从而自己发现信息；而坐在屏幕前看影片无法获得这样的体验。","source":"original","number":22}]},{"id":"babies-5e2231054a","term":"be interested in","type":"phrase","sourceOrder":63,"zh":"对……感兴趣","pos":"搭配／句型","ipa":"biː ˈɪntrəstɪd ɪn","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"When you give a baby a present or gift, some of them are more interested in the wrapping paper than the present itself.","zh":"当你送给婴儿一份礼物时，有些婴儿对包装纸的兴趣比礼物本身更大。","source":"original","number":28}]},{"id":"babies-0103e6951f","term":"wrapping paper","type":"phrase","sourceOrder":64,"zh":"包装纸","pos":"搭配／句型","ipa":"ˈræpɪŋ ˈpeɪpə","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"When you give a baby a present or gift, some of them are more interested in the wrapping paper than the present itself.","zh":"当你送给婴儿一份礼物时，有些婴儿对包装纸的兴趣比礼物本身更大。","source":"original","number":28}]},{"id":"babies-81aff3b0a5","term":"pretty much every baby","type":"phrase","sourceOrder":65,"zh":"几乎每个婴儿","pos":"搭配／句型","ipa":"ˈprɪti mʌtʃ ˈevri ˈbeɪbi","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"The research shows that pretty much every baby prefers the paper to the present, whether male or female.","zh":"研究显示，几乎每个婴儿都更喜欢包装纸，而不是礼物，无论男女。","source":"original","number":30}]},{"id":"babies-fe67d786b9","term":"prefer A to B","type":"phrase","sourceOrder":66,"zh":"比起B更喜欢A","pos":"搭配／句型","ipa":"prɪˈfɜː eɪ tə biː","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"The research shows that pretty much every baby prefers the paper to the present, whether male or female.","zh":"研究显示，几乎每个婴儿都更喜欢包装纸，而不是礼物，无论男女。","source":"original","number":30}]},{"id":"babies-b411152512","term":"whether male or female","type":"phrase","sourceOrder":67,"zh":"无论男孩还是女孩","pos":"搭配／句型","ipa":"ˈweðə meɪl ɔː ˈfiːmeɪl","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"The research shows that pretty much every baby prefers the paper to the present, whether male or female.","zh":"研究显示，几乎每个婴儿都更喜欢包装纸，而不是礼物，无论男女。","source":"original","number":30}]},{"id":"babies-2b71f498a7","term":"stimulate the baby's senses","type":"phrase","sourceOrder":68,"zh":"刺激婴儿的感官","pos":"搭配／句型","ipa":"ˈstɪmjuleɪt ðə ˈbeɪbiz ˈsensɪz","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"It seems that playing with the paper or ribbons or box stimulates the baby's senses.","zh":"看来，玩包装纸、丝带或盒子能刺激婴儿的感官。","source":"original","number":35}]},{"id":"babies-b8459c33f1","term":"brain scans","type":"phrase","sourceOrder":69,"zh":"脑部扫描","pos":"搭配／句型","ipa":"breɪn skænz","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"And brain scans have shown that sight, sound, touch, smell, and taste are all stimulated in this way.","zh":"脑部扫描表明，视觉、听觉、触觉、嗅觉和味觉都会以这种方式受到刺激。","source":"original","number":37}]},{"id":"babies-db7213ed1f","term":"in this way","type":"phrase","sourceOrder":70,"zh":"以这种方式","pos":"搭配／句型","ipa":"ɪn ðɪs weɪ","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"And brain scans have shown that sight, sound, touch, smell, and taste are all stimulated in this way.","zh":"脑部扫描表明，视觉、听觉、触觉、嗅觉和味觉都会以这种方式受到刺激。","source":"original","number":37}]},{"id":"babies-4e1bce40cc","term":"learn by playing","type":"phrase","sourceOrder":71,"zh":"通过玩耍学习","pos":"搭配／句型","ipa":"lɜːn baɪ ˈpleɪɪŋ","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"But it shows us that babies learn by playing.","zh":"但这也说明，婴儿是通过玩耍来学习的。","source":"original","number":42}]},{"id":"babies-0c0f873a0a","term":"wrap up presents","type":"phrase","sourceOrder":72,"zh":"包装礼物","pos":"搭配／句型","ipa":"ræp ʌp ˈprezənts","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"So we shouldn't stop wrapping up babies' presents.","zh":"所以我们不应该停止给婴儿的礼物包装起来。","source":"original","number":43}]},{"id":"babies-e4ea555a1f","term":"bilingual experiment","type":"phrase","sourceOrder":73,"zh":"双语实验","pos":"搭配／句型","ipa":"baɪˈlɪŋɡwəl ɪkˈsperɪmənt","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"There was a really interesting bilingual experiment in Spain.","zh":"西班牙曾进行过一项非常有趣的双语实验。","source":"original","number":46}]},{"id":"babies-fdf9e8a2ef","term":"research subjects","type":"phrase","sourceOrder":74,"zh":"研究对象；受试者","pos":"搭配／句型","ipa":"rɪˈsɜːtʃ ˈsʌbdʒɪkts","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"So the research subjects were in different schools?","zh":"所以实验对象来自不同学校？","source":"original","number":48}]},{"id":"babies-b06e3bcbfc","term":"focus on play and social interaction","type":"phrase","sourceOrder":75,"zh":"注重玩耍和社交互动","pos":"搭配／句型","ipa":"ˈfəʊkəs ɒn pleɪ ənd ˈsəʊʃəl ˌɪntərˈækʃən","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"They had been trained to use a style that focused on play and social interaction.","zh":"这些教师此前都接受过培训，采用侧重游戏与社交互动的教学方式。","source":"original","number":50}]},{"id":"babies-500c30f6f9","term":"be standardized across all the schools","type":"phrase","sourceOrder":76,"zh":"在所有学校实行统一标准","pos":"搭配／句型","ipa":"biː ˈstændədaɪzd əˈkrɒs ɔːl ðə skuːlz","stars":4,"note":"","paragraph":"听力原文","examples":[{"en":"So because of that, the experiment was standardized across all the schools.","zh":"因此，实验在所有学校都遵循统一标准。","source":"original","number":51}]},{"id":"babies-fa5fceee75","term":"an average of","type":"phrase","sourceOrder":77,"zh":"平均为……","pos":"搭配／句型","ipa":"ən ˈævərɪdʒ əv","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"But at the end of the experiment, each child could produce an average of seventy-four English words or phrases.","zh":"但在实验结束时，每名儿童平均能说出74个英语单词或短语。","source":"original","number":58}]},{"id":"babies-f6b7e6f8b3","term":"follow-up testing","type":"phrase","sourceOrder":78,"zh":"后续测试","pos":"搭配／句型","ipa":"ˈfɒləʊ ʌp ˈtestɪŋ","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Well, follow-up testing showed that the classes had a long-term benefit.","zh":"嗯，后续测试显示，这些课程具有长期益处。","source":"original","number":60}]},{"id":"babies-453b2bba42","term":"long-term benefit","type":"phrase","sourceOrder":79,"zh":"长期益处","pos":"搭配／句型","ipa":"ˌlɒŋ ˈtɜːm ˈbenɪfɪt","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Well, follow-up testing showed that the classes had a long-term benefit.","zh":"嗯，后续测试显示，这些课程具有长期益处。","source":"original","number":60}]},{"id":"babies-1fc3b3679d","term":"electrical brain activity","type":"phrase","sourceOrder":80,"zh":"脑部电活动","pos":"搭配／句型","ipa":"ɪˈlektrɪkəl breɪn ækˈtɪvəti","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"And Dr. Pritchard monitored the babies' electrical brain activity.","zh":"Pritchard 博士还监测了婴儿大脑的电活动。","source":"original","number":74}]},{"id":"babies-ba3221de99","term":"imitate their behavior","type":"phrase","sourceOrder":81,"zh":"模仿他们的行为","pos":"搭配／句型","ipa":"ˈɪmɪteɪt ðeə bɪˈheɪvjə","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"The results showed that babies were happiest when parents or caregivers imitated their behavior.","zh":"结果显示，当父母或照顾者模仿他们的行为时，婴儿最开心。","source":"original","number":75}]},{"id":"babies-08fffd8a50","term":"pick up the pen","type":"phrase","sourceOrder":82,"zh":"捡起笔","pos":"搭配／句型","ipa":"pɪk ʌp ðə pen","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"What they often did, though, was pick up the pen.","zh":"不过，他们经常做的是把笔捡起来。","source":"original","number":83}]},{"id":"babies-5b05dc0bce","term":"give someone assistance","type":"phrase","sourceOrder":83,"zh":"给某人帮助","pos":"搭配／句型","ipa":"ɡɪv ˈsʌmwʌn əˈsɪstəns","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"They wanted to give someone assistance if they could, if they thought someone else had a problem.","zh":"如果可以，而且他们认为别人遇到了困难，他们就愿意帮助对方。","source":"original","number":84}]},{"id":"babies-992de3d960","term":"be more likely to","type":"phrase","sourceOrder":84,"zh":"更有可能……","pos":"搭配／句型","ipa":"biː mɔː ˈlaɪkli tə","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"So I think that shows how babies are more likely to learn by working with caregivers and teachers rather than in isolation.","zh":"所以我认为，这说明婴幼儿与照顾者、教师一起活动，比独自学习更有可能学到东西。","source":"original","number":85}]},{"id":"babies-d83fbb09c9","term":"rather than in isolation","type":"phrase","sourceOrder":85,"zh":"而非独自一人","pos":"搭配／句型","ipa":"ˈrɑːðə ðən ɪn ˌaɪsəˈleɪʃən","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"So I think that shows how babies are more likely to learn by working with caregivers and teachers rather than in isolation.","zh":"所以我认为，这说明婴幼儿与照顾者、教师一起活动，比独自学习更有可能学到东西。","source":"original","number":85}]},{"id":"babies-cd062e90c2","term":"switch on a light","type":"phrase","sourceOrder":86,"zh":"打开一盏灯","pos":"搭配／句型","ipa":"swɪtʃ ɒn ə laɪt","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"Some buttons switched on a light, and some didn't.","zh":"有些按钮能打开灯，而有些不能。","source":"original","number":90}]},{"id":"babies-e4a286cf29","term":"come on","type":"phrase","sourceOrder":87,"zh":"亮起","pos":"搭配／句型","ipa":"kʌm ɒn","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"You mean they knew the light would come on?","zh":"你是说，他们知道灯会亮起来？","source":"original","number":92}]},{"id":"babies-6337d99f40","term":"as a result of","type":"phrase","sourceOrder":88,"zh":"作为……的结果；由于","pos":"搭配／句型","ipa":"əz ə rɪˈzʌlt əv","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"He believes they recognized that a certain thing would happen as a result of a certain action.","zh":"他认为婴儿意识到，某一特定动作会导致某个特定结果。","source":"original","number":94}]},{"id":"babies-eee8666556","term":"have implications for learning","type":"phrase","sourceOrder":89,"zh":"对学习有启示","pos":"搭配／句型","ipa":"həv ˌɪmplɪˈkeɪʃənz fə ˈlɜːnɪŋ","stars":4,"note":"","paragraph":"听力原文","examples":[{"en":"So maybe that has implications for learning.","zh":"所以这或许对学习研究具有启示意义。","source":"original","number":95}]},{"id":"babies-88719356d3","term":"as young as sixteen months","type":"phrase","sourceOrder":90,"zh":"年仅十六个月","pos":"搭配／句型","ipa":"əz jʌŋ əz ˌsɪksˈtiːn mʌnθs","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"This showed that babies as young as sixteen months have some knowledge of how language is structured.","zh":"这表明，甚至只有16个月大的婴儿也对语言的结构有所了解。","source":"original","number":98}]},{"id":"babies-23c882a051","term":"the function of nouns and verbs","type":"phrase","sourceOrder":91,"zh":"名词和动词的功能","pos":"搭配／句型","ipa":"ðə ˈfʌŋkʃən əv naʊnz ənd vɜːbz","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"In a simple sense, they seem to know the function of nouns and verbs, and the researchers believe this is linked to the way they learn the meaning of new words.","zh":"简单来说，他们似乎知道名词和动词的作用；研究者认为，这与他们学习新词含义的方式有关。","source":"original","number":99}]},{"id":"babies-596fab4540","term":"be linked to","type":"phrase","sourceOrder":92,"zh":"与……有关联","pos":"搭配／句型","ipa":"biː lɪŋkt tə","stars":3,"note":"","paragraph":"听力原文","examples":[{"en":"In a simple sense, they seem to know the function of nouns and verbs, and the researchers believe this is linked to the way they learn the meaning of new words.","zh":"简单来说，他们似乎知道名词和动词的作用；研究者认为，这与他们学习新词含义的方式有关。","source":"original","number":99}]}],"sentences":[{"en":"First, you have some time to look at questions twenty-one to twenty-six.","zh":"首先，你有一些时间阅读第21至26题。","speaker":"考官 / Speaker 0","paragraph":"听力原文","note":"拆解  First 表示流程顺序；have some time to do sth. 有时间做某事；look at questions 看题。\n听力提示  题号 twenty-one to twenty-six 是范围，不是答案内容。"},{"en":"Now listen carefully and answer questions twenty-one to twenty-six.","zh":"现在仔细听录音并回答第21至26题。","speaker":"考官 / Speaker 0","paragraph":"听力原文","note":"拆解  listen carefully 仔细听；answer questions 回答问题；Now 指令转入播放阶段。\n听力提示  听力指令句通常不计入学术讨论内容。"},{"en":"So Daniel, shall we compare a few ideas for our assignment on how babies and children learn?","zh":"那么，Daniel，我们来比较一下关于婴幼儿如何学习这份作业的几个想法，好吗？","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  shall we...? 提建议；compare a few ideas 比较几个想法；assignment on... 关于……的作业；how babies and children learn 是宾语从句。\n听力提示  开场点明全文主题：how babies and children learn。"},{"en":"Good idea.","zh":"好主意。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  省略句，完整含义是 That's a good idea；用于同意建议。\n听力提示  表示赞同，不提供研究事实。"},{"en":"I've started the reading.","zh":"我已经开始阅读资料了。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  I've = I have；have started 是现在完成时；the reading 指作业要求的阅读材料。\n听力提示  暗示后面将介绍读到的研究。"},{"en":"One thing I read about was these learning videos.","zh":"我读到的其中一项内容是这些学习视频。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  One thing (that) I read about：省略关系代词的定语从句；learning videos 学习视频。\n听力提示  引出第一个研究话题：视频学习。"},{"en":"Oh, yeah.","zh":"哦，对。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  口语应答，表示想起来或表示认同；yeah = yes。\n听力提示  短回应不代表实质性研究结论。"},{"en":"I read about learning videos.","zh":"我也读过关于学习视频的内容。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  read about sth. 阅读有关……的资料；read 在此为过去式，拼写不变。\n听力提示  与上一句形成信息呼应。"},{"en":"The baby watches a short film with some basic vocabulary, maths, and science, and they learn as they watch.","zh":"婴儿观看包含基础词汇、数学和科学知识的短片，并在观看时学习。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  watch a short film 看短片；with 引出影片内容；as they watch = while they are watching，表示同时发生。\n听力提示  这是视频学习的设想，不是被研究证实的结论。"},{"en":"That's the idea.","zh":"理论上就是这样。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  That 指代上一句视频边看边学的设想；the idea 表示方案的基本思路。\n听力提示  注意 speaker 将“设想”与下一段“研究发现”区分开。"},{"en":"Certainly, babies will pay attention to videos for long periods of time.","zh":"当然，婴儿确实会长时间关注视频。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  Certainly 当然；pay attention to 关注；for long periods of time 长时间地。\n听力提示  能够专注 ≠ 能够有效学习。"},{"en":"Yeah, but there's been research to show that babies don't learn effectively from screens.","zh":"是的，但已有研究表明，婴儿无法有效地通过屏幕学习。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  there's been = there has been，现在完成时；research to show that... 表明……的研究；effectively 有效地；from screens 通过屏幕。\n听力提示  Yeah, but 是强转折，真正研究结论在 but 之后。"},{"en":"Actually, they learn by interacting with their parents and other caregivers.","zh":"实际上，他们通过与父母及其他照顾者互动来学习。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  Actually 用来纠正/补充；learn by doing 通过做某事来学习；interact with 与……互动；caregivers 照顾者。\n听力提示  潜在同义替换：interaction = engagement with adults。"},{"en":"That's the best approach.","zh":"这是最好的方式。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  approach 在这里是“方法”；best 为最高级；That 指前句的互动式学习。\n听力提示  正确指代对象是 interacting with caregivers，而不是 videos。"},{"en":"Hmm.","zh":"嗯。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  思考性的语气词；表示在消化对方信息。\n听力提示  无独立学术信息。"},{"en":"It's interesting.","zh":"这很有意思。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  It 指前述研究发现；interesting 令人感兴趣的。\n听力提示  评价句，不是研究结果本身。"},{"en":"Another issue with learning videos is that babies ought to have playtime.","zh":"学习视频的另一个问题是，婴儿应该有玩耍的时间。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  Another issue with... ……的另一个问题；is that 引导表语从句；ought to = should；playtime 玩耍时间。\n听力提示  话题从屏幕学习转到自由游戏。"},{"en":"You mean in a group?","zh":"你是指集体一起玩吗？","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  You mean...? 你是说……吗；in a group 集体地。\n听力提示  这是试探性问题，不应立即将 group 判作正确答案。"},{"en":"Not necessarily.","zh":"不一定。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  necessarily 必然地；Not necessarily 是固定短语，否定“必须在小组中”。\n听力提示  强干扰排除信号。"},{"en":"It can be alone, actually.","zh":"实际上，也可以自己一个人玩。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  alone 独自地；actually 用于修正刚才的理解；It 指 playtime。\n听力提示  核心不是集体或独自，而是后一句的探索行为。"},{"en":"But what's important is that they investigate their own environment.","zh":"但重要的是，他们要探索自己周围的环境。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  what's important 是名词性从句作主语；is that... 是表语从句；investigate 探索；environment 环境。\n听力提示  What's important is that... 明确标示答案重点。"},{"en":"They should examine the objects around them and experiment, so they discover information for themselves, and they don't get that sitting in front of a film.","zh":"他们应该观察周围的物体并动手尝试，从而自己发现信息；而坐在屏幕前看影片无法获得这样的体验。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  examine the objects 观察物体；experiment 在此作动词“尝试”；so 表结果；for themselves 自己独立地；sitting... 现在分词短语说明情境。\n听力提示  同义替换：discover for themselves = learn through exploration；屏幕观看与动手探索形成对比。"},{"en":"That's a good point.","zh":"这一点说得很好。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  a good point 有道理的观点；That 指前句关于主动探索的论点。\n听力提示  赞同对方观点，推动话题过渡。"},{"en":"Then I also thought I'd write about the present research in my assignment.","zh":"另外，我还想在作业里写写关于礼物的研究。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  thought I'd = thought I would；write about... 写关于……；present 在此是名词“礼物”，不是形容词“当前的”。\n听力提示  重要歧义：present research 在上下文中指“礼物研究”，不是“当前研究”。"},{"en":"Oh, yeah.","zh":"哦，对。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  常见对话接应语，用于表示知道这一话题。\n听力提示  不涉及题目答案。"},{"en":"I read a bit about the present research.","zh":"我也读过一点关于礼物的研究。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  a bit about = a little about；present 此处仍指“礼物”。\n听力提示  结合后文 wrapping paper 判断 present 的词义。"},{"en":"And it's true, isn't it?","zh":"这确实是这样，对吧？","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  反意疑问句：肯定陈述 + 否定附加问句 isn't it?；it 指下面将说的观察现象。\n听力提示  标示说话者以为自己理解研究，但马上会被修正。"},{"en":"When you give a baby a present or gift, some of them are more interested in the wrapping paper than the present itself.","zh":"当你送给婴儿一份礼物时，有些婴儿对包装纸的兴趣比礼物本身更大。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  give sb. sth. 给某人某物；be more interested in A than B 对A比B更感兴趣；itself 强调礼物本身。\n听力提示  some of them 是后面专门纠正的干扰点。"},{"en":"But it's not some of them.","zh":"但并不只是其中一部分婴儿。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  not some of them 在语境中否定“仅部分”这一范围；But 引导纠正。\n听力提示  听到否定后要修改前面的数量判断。"},{"en":"The research shows that pretty much every baby prefers the paper to the present, whether male or female.","zh":"研究显示，几乎每个婴儿都更喜欢包装纸，而不是礼物，无论男女。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  pretty much = almost；prefer A to B 比起B更喜欢A；whether male or female 无论男婴或女婴。\n听力提示  关键替换：some → pretty much every；排除“只在某一性别中普遍”。"},{"en":"It's just a human characteristic.","zh":"这只是人类的一种普遍特征。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  human characteristic 人类特征；just 在此表示“就是/不过是”。\n听力提示  进一步强调普遍性，而非个别差异。"},{"en":"Really?","zh":"真的吗？","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  语调往往表示吃惊或请求确认。\n听力提示  暗示前一句结果出乎意料。"},{"en":"I thought there'd be more exceptions.","zh":"我原以为会有更多例外。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  I thought... 过去的预期；there'd = there would；exceptions 例外。\n听力提示  与 every baby 相对应，关注例外是否存在。"},{"en":"Apparently not.","zh":"显然并非如此。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  Apparently 看来、据说；not 代替完整句“there aren't more exceptions”。\n听力提示  简短否定，再次确认几乎无例外。"},{"en":"It seems that playing with the paper or ribbons or box stimulates the baby's senses.","zh":"看来，玩包装纸、丝带或盒子能刺激婴儿的感官。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  It seems that... 看起来……；playing with... 动名词短语作主语；stimulates 谓语单数；senses 感官。\n听力提示  研究解释的是“感官刺激”，不是包装材料的美观。"},{"en":"They touch everything, climb into the box, put the ribbon into their mouths.","zh":"他们会摸各种东西、爬进盒子里，还会把丝带放进嘴里。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  并列动词 touch / climb / put；climb into 爬进；put... into one's mouth 放进嘴里。\n听力提示  三个例子分别体现触碰、动作探索和口部体验。"},{"en":"And brain scans have shown that sight, sound, touch, smell, and taste are all stimulated in this way.","zh":"脑部扫描表明，视觉、听觉、触觉、嗅觉和味觉都会以这种方式受到刺激。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  brain scans 脑部扫描；have shown 现在完成时；sight / sound / touch / smell / taste 五种感官；are stimulated 被动语态。\n听力提示  五感词汇可能被改写为 sensory development / multiple senses。"},{"en":"It's amazing the research has produced so much specific information just from studying presents.","zh":"令人惊讶的是，研究者仅通过研究礼物就获得了如此多的具体信息。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  It's amazing (that)... 令人惊讶的是……；has produced 已产生；so much + 不可数名词 information；just from 仅仅通过。\n听力提示  Maya 惊讶的是研究信息丰富而具体。"},{"en":"I hadn't expected that.","zh":"我之前完全没想到。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  hadn't expected 过去完成时，表示在知道结果之前没有预料到；that 指研究结果。\n听力提示  同义替换：unexpected / surprising findings。"},{"en":"The results cover so many different aspects of baby behavior.","zh":"这些结果涉及婴儿行为的很多不同方面。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  cover 在此为“涵盖”；aspects of... ……的各个方面；behavior 行为。\n听力提示  关注研究结果的广泛性。"},{"en":"Yeah, exactly.","zh":"对，正是如此。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  exactly 表示完全同意。\n听力提示  强化对上一观点的认可。"},{"en":"But it shows us that babies learn by playing.","zh":"但这也说明，婴儿是通过玩耍来学习的。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  show sb. that... 向某人表明……；learn by doing 通过做某事学习。\n听力提示  礼物研究最终结论：learning through play。"},{"en":"So we shouldn't stop wrapping up babies' presents.","zh":"所以我们不应该停止给婴儿的礼物包装起来。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  shouldn't = should not；stop doing sth. 停止做某事；wrap up 包装；babies' 为复数所有格。\n听力提示  带有幽默的生活应用，不要误解为“禁止包装”。"},{"en":"No, definitely not.","zh":"不，当然不应该停止。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  definitely not 绝对不是；No 在这里回应否定句，表示不应停止包装。\n听力提示  英语否定问答容易绕，结合语义判断态度。"},{"en":"Then I also read about babies and second languages.","zh":"我还读过婴儿学习第二语言的研究。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  second language 第二语言；read about... 读到关于……的内容。\n听力提示  引出双语学习话题。"},{"en":"There was a really interesting bilingual experiment in Spain.","zh":"西班牙曾进行过一项非常有趣的双语实验。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  there was 引出过去存在的事物；bilingual 双语的；experiment 实验。\n听力提示  地点 Spain 及 bilingual 可用于研究匹配。"},{"en":"They tried teaching English to a group of two hundred and eighty Spanish children in different preschools.","zh":"他们尝试在不同幼儿园里教280名西班牙儿童英语。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  try doing sth. 尝试采用某方法；teach sth. to sb. 教某人某事；two hundred and eighty = 280；preschools 学前教育机构。\n听力提示  数字280、不同学校都是定位信息。"},{"en":"So the research subjects were in different schools?","zh":"所以实验对象来自不同学校？","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  research subjects 研究对象；were in 表所处地点；So 引出确认。\n听力提示  仅在确认学校不同，不代表教学不同。"},{"en":"Yes, but the researchers deliberately selected teachers who all had the same education.","zh":"是的，但研究人员有意选择了教育背景相同的教师。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  deliberately 有意地；selected 选择；who all had the same education 是限定性定语从句，修饰 teachers。\n听力提示  转折重点：同样的教育背景，这是实验控制条件。"},{"en":"They had been trained to use a style that focused on play and social interaction.","zh":"这些教师此前都接受过培训，采用侧重游戏与社交互动的教学方式。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  had been trained 过去完成时的被动语态；be trained to do 被培训去做；that focused on... 修饰 style；social interaction 社交互动。\n听力提示  同义替换：teaching style = instructional approach；play-based methods。"},{"en":"So because of that, the experiment was standardized across all the schools.","zh":"因此，实验在所有学校都遵循统一标准。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  because of that 因此；was standardized 被动语态“被标准化”；across all the schools 在所有学校之间。\n听力提示  因果：教师培训一致 → 实验可比较；不能推断每校用不同方法。"},{"en":"That's really important.","zh":"这一点非常重要。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  That 指实验标准化；really 加强程度。\n听力提示  评价重复突出控制变量的重要性。"},{"en":"Yeah, I agree.","zh":"对，我同意。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  I agree 表示赞同。\n听力提示  口语反馈，不引入新事实。"},{"en":"That was a great idea.","zh":"那真是个好主意。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  That 指刻意统一教师资质和教学方式；great idea 好办法。\n听力提示  赞同实验设计，不是指录制视频。"},{"en":"The subjects were aged between seven months and three years old, and the children were given a one-hour English lesson for eighteen weeks.","zh":"受试儿童年龄介于7个月到3岁之间，连续18周接受每次一小时的英语课。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  be aged between A and B 年龄介于……；were given 是双宾结构的被动语态；one-hour 是复合形容词；for eighteen weeks 表持续18周。\n听力提示  牢记：7个月—3岁、一小时、18周；原文未明确说明每周具体上课频次。"},{"en":"Did they seem to enjoy the lessons?","zh":"他们看起来喜欢这些课程吗？","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  seem to do 看起来似乎做某事；enjoy the lessons 喜欢课程。\n听力提示  这是一个提问，尚无证据可以回答。"},{"en":"I don't have any information on that.","zh":"我没有关于这一点的资料。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  information on sth. 关于某事的信息；that 指儿童是否喜欢课程。\n听力提示  重要：不能推断孩子喜欢或不喜欢。"},{"en":"But at the end of the experiment, each child could produce an average of seventy-four English words or phrases.","zh":"但在实验结束时，每名儿童平均能说出74个英语单词或短语。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  at the end of 在……结束时；produce 在语言测试中指“说出/使用”；an average of 平均；words or phrases 单词或短语。\n听力提示  74是输出能力平均数，不是所有儿童完全相同。"},{"en":"But did they remember them?","zh":"但他们后来还记得这些词语吗？","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  remember them 记住它们；them 指英语词或短语；But 切换到长期效果。\n听力提示  留意随后的 follow-up testing。"},{"en":"Well, follow-up testing showed that the classes had a long-term benefit.","zh":"嗯，后续测试显示，这些课程具有长期益处。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  follow-up testing 后续测试；showed that... 显示……；long-term benefit 长期益处。\n听力提示  答案为长期效果存在；不是只看实验结束当下的表现。"},{"en":"Yes.","zh":"是的。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  肯定应答，确认前述问题。\n听力提示  与长期记忆问题一起理解。"},{"en":"Wow, that's remarkable, especially considering some of the children were so young.","zh":"哇，这很了不起，尤其考虑到一些孩子年龄那么小。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  remarkable 非凡的；especially considering... 尤其考虑到……；so young 年龄如此小。\n听力提示  说话者惊讶的是很小的儿童也有显著学习效果。"},{"en":"I think so too.","zh":"我也这么认为。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  think so 表示持相同观点；too 也。\n听力提示  态度一致。"},{"en":"It really shows how babies and small children can learn through playing.","zh":"这充分表明婴儿和幼儿能够通过游戏来学习。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  show how... 表明如何……；through playing 通过玩耍；really 加强语气。\n听力提示  回扣文章主旨：通过游戏学习。"},{"en":"Yeah.","zh":"对。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  简短认可。\n听力提示  不是新研究结果。"},{"en":"I wonder if other schools will try the same thing in future.","zh":"我想知道今后其他学校是否会尝试同样的方法。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  I wonder if... 不知道是否……；the same thing 同样教学方式；in future 今后。\n听力提示  只是对未来可能性的猜测，不能当作既成事实。"},{"en":"It'll be interesting to see what happens.","zh":"看看接下来会怎样将很有意思。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  It'll = It will；It will be + adj. + to do；what happens 宾语从句。\n听力提示  没有提供其他学校已经实施的证据。"},{"en":"Before you hear the rest of the talk, you have some time to look at questions twenty-seven to thirty.","zh":"听余下部分之前，你有一些时间阅读第27至30题。","speaker":"考官 / Speaker 0","paragraph":"听力原文","note":"拆解  Before 引导时间状语从句；the rest of 剩余部分；look at 看题。\n听力提示  题号切换为27—30。"},{"en":"Now listen and answer questions twenty-seven to thirty.","zh":"现在请听录音并回答第27至30题。","speaker":"考官 / Speaker 0","paragraph":"听力原文","note":"拆解  祈使句 listen and answer；twenty-seven to thirty 表示题号区间。\n听力提示  准备跟踪四项不同研究。"},{"en":"So Maya, let's discuss some more ideas about how babies learn.","zh":"那么，Maya，我们再讨论一些婴儿如何学习的想法吧。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  let's + 动词原形 提议；some more 更多一些；how babies learn 名词性从句。\n听力提示  标志第二段学术讨论开始。"},{"en":"What other research have you read about?","zh":"你还读过哪些研究？","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  what other research 什么其他研究；have you read about 是现在完成时疑问句。\n听力提示  提示进入研究列表。"},{"en":"Well, I read about Dr. Pritchard's study.","zh":"嗯，我读过 Pritchard 博士的研究。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  Dr. = Doctor；Pritchard's 所有格；study 研究。\n听力提示  人名 Pritchard 是后面匹配题的定位点。"},{"en":"In her experiment, babies were given toys to play with, and their caregivers sometimes repeated the same movements as the baby and sometimes did something different.","zh":"在她的实验中，婴儿得到玩具进行玩耍；照顾者有时重复婴儿做的动作，有时做不同的动作。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  were given toys 是被动语态；to play with 不定式作后置定语；the same... as... 与……相同；sometimes... and sometimes... 比较两种实验条件。\n听力提示  实验自变量：照顾者是否模仿宝宝动作。"},{"en":"And Dr. Pritchard monitored the babies' electrical brain activity.","zh":"Pritchard 博士还监测了婴儿大脑的电活动。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  monitored 监测；electrical brain activity 大脑电活动；babies' 复数所有格。\n听力提示  监测脑活动是研究方法，而非最终结果。"},{"en":"The results showed that babies were happiest when parents or caregivers imitated their behavior.","zh":"结果显示，当父母或照顾者模仿他们的行为时，婴儿最开心。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  results showed that... 结果表明；were happiest 最高级；when 时间从句；imitated their behavior 模仿他们的行为。\n听力提示  核心答案：imitation / copying baby's actions。"},{"en":"Maybe that could be used as a teaching tool.","zh":"也许这种做法可以用作教学工具。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  Maybe 也许；could be used 被动语态，表示可能用途；teaching tool 教学工具；that 指模仿行为。\n听力提示  这是建议或推测，区别于已证实的实验结果。"},{"en":"Yeah, absolutely.","zh":"对，完全赞同。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  absolutely 表示强烈肯定。\n听力提示  说话者认可可能的教学应用。"},{"en":"Then I read about a study of three-year-olds.","zh":"然后我读了一项关于三岁儿童的研究。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  three-year-olds 三岁儿童（名词，复数）；a study of... 关于……的研究。\n听力提示  年龄3岁是定位线索。"},{"en":"This was interesting.","zh":"这项研究很有意思。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  This 指三岁儿童研究；interesting 为主观评价。\n听力提示  引出实验细节。"},{"en":"The researchers experimented by doing things like dropping a pen or knocking something off a desk.","zh":"研究人员通过做一些事情来开展实验，例如把笔掉在地上，或把某物从桌上碰落。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  experimented by doing 通过做……实验；things like... 比如……；drop a pen 掉落一支笔；knock sth. off 将某物碰落。\n听力提示  这些动作是研究者做的，不是儿童模仿的动作。"},{"en":"And did the children do the same thing?","zh":"那么，孩子们也做了相同的事情吗？","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  do the same thing 做同样的事；did...do...? 一般过去时疑问句。\n听力提示  这是用于设置干扰的猜测。"},{"en":"No.","zh":"没有。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  直接否定上一句的猜测。\n听力提示  排除“儿童复制研究人员的错误动作”。"},{"en":"What they often did, though, was pick up the pen.","zh":"不过，他们经常做的是把笔捡起来。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  What they often did 是主语从句；was pick up the pen 是表语，省略 to 的不定式结构；though 插入语，表示转折；pick up 捡起。\n听力提示  关注 children help，而非 imitate。"},{"en":"They wanted to give someone assistance if they could, if they thought someone else had a problem.","zh":"如果可以，而且他们认为别人遇到了困难，他们就愿意帮助对方。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  give someone assistance = help someone；if they could 与 if they thought... 为条件状语从句；someone else 其他人。\n听力提示  核心：愿意主动帮助遇到问题的人。"},{"en":"So I think that shows how babies are more likely to learn by working with caregivers and teachers rather than in isolation.","zh":"所以我认为，这说明婴幼儿与照顾者、教师一起活动，比独自学习更有可能学到东西。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  are more likely to 更有可能；learn by working with 通过协作学习；rather than 而不是；in isolation 独自、孤立地。\n听力提示  这是说话者的进一步推论，不等于实验直接测量了学习成绩。"},{"en":"Then have you heard of Professor Michelson?","zh":"那么，你听说过 Michelson 教授吗？","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  have heard of 听说过；Professor 教授。\n听力提示  人名提示切换研究对象。"},{"en":"Is he a linguist?","zh":"他是一位语言学家吗？","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  linguist 语言学家；Is he...? 一般疑问句。\n听力提示  下一句否定，语言学家身份是干扰信息。"},{"en":"You're thinking of someone else.","zh":"你想到的是另外一个人。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  think of 想到；someone else 别的某个人。\n听力提示  纠正对教授身份的误认。"},{"en":"Professor Michelson did a study where babies had to push buttons.","zh":"Michelson 教授做过一项实验，在实验中婴儿需要按按钮。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  a study where... where 引导限定性定语从句，表示实验情境；had to push buttons 必须按按钮。\n听力提示  关注实验动作：push buttons。"},{"en":"Some buttons switched on a light, and some didn't.","zh":"有些按钮能打开灯，而有些不能。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  switch on 打开（电器或灯）；didn't = didn't switch on a light，为避免重复的省略。\n听力提示  两类按钮构成结果对照。"},{"en":"And after a little experimentation, the babies nearly always pushed a button that switched on a light.","zh":"经过一点尝试后，婴儿几乎总是选择能够打开灯的按钮。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  after a little experimentation 经过试验；nearly always 几乎总是；that switched on a light 是定语从句修饰 button。\n听力提示  关键：反复选择“会亮”的按钮，说明形成了预期。"},{"en":"You mean they knew the light would come on?","zh":"你是说，他们知道灯会亮起来？","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  You mean...? 请求确认；would come on 过去视角下的将来结果；come on （灯）亮起。\n听力提示  将动作与后果联系起来。"},{"en":"Professor Michelson thinks so.","zh":"Michelson 教授认为是这样。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  thinks so = thinks that they knew the light would come on；so 代替整个观点。\n听力提示  注意归属：这是研究者的解释。"},{"en":"He believes they recognized that a certain thing would happen as a result of a certain action.","zh":"他认为婴儿意识到，某一特定动作会导致某个特定结果。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  believes (that)... 认为……；recognized that... 认识到……；as a result of 因为、作为……的结果；a certain action 特定动作。\n听力提示  匹配关键：cause and effect / action-consequence relationship。"},{"en":"So maybe that has implications for learning.","zh":"所以这或许对学习研究具有启示意义。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  have implications for 对……有影响或启示；maybe 也许；that 指婴儿能感知因果联系。\n听力提示  “maybe”强调推测，不要夸大为已经验证的教育成果。"},{"en":"Interesting.","zh":"有意思。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  单独的形容词用于回应。\n听力提示  无新增研究事实。"},{"en":"I also looked at a study in the United States.","zh":"我还看了一项在美国开展的研究。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  look at a study 阅读/研究一项研究；in the United States 在美国。\n听力提示  研究地点用于匹配不同项目。"},{"en":"This showed that babies as young as sixteen months have some knowledge of how language is structured.","zh":"这表明，甚至只有16个月大的婴儿也对语言的结构有所了解。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  as young as sixteen months 甚至小到16个月；have knowledge of 了解；how language is structured 是介词 of 的宾语从句，其中 is structured 为被动语态。\n听力提示  数字16个月与 language structure 为定位核心。"},{"en":"In a simple sense, they seem to know the function of nouns and verbs, and the researchers believe this is linked to the way they learn the meaning of new words.","zh":"简单来说，他们似乎知道名词和动词的作用；研究者认为，这与他们学习新词含义的方式有关。","speaker":"Daniel / Speaker 2","paragraph":"听力原文","note":"拆解  in a simple sense 简单地说；seem to know 似乎知道；the function of nouns and verbs 名词与动词的功能；be linked to 与……有关；the way (that) they learn... 学习……的方式。\n听力提示  核心研究：幼儿已有初步句法/词性知识；与新词词义学习有关。"},{"en":"Oh, really?","zh":"哦，真的吗？","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  口语惊讶回应；really 强调意外。\n听力提示  体现 Maya 对幼儿语言能力感到惊讶。"},{"en":"Amazing they start so young.","zh":"真惊人，他们这么小就开始具备这种能力了。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  口语省略句，完整形式为 It's amazing that they start so young；so young 如此年幼。\n听力提示  这是评价，不是说儿童已完全掌握语法。"},{"en":"I'd like to read about that study 'cause that sounds so amazing.","zh":"我想读读那项研究，因为听起来实在太惊人了。","speaker":"Maya / Speaker 1","paragraph":"听力原文","note":"拆解  I'd like = I would like；would like to do 想做某事；'cause 是 because 的口语缩略；sound + 形容词 听起来……。\n听力提示  原转写把 'cause 单独切开，此处按实际语义合并；这是兴趣表达。"},{"en":"That is the end of part three.","zh":"第三部分到此结束。","speaker":"考官 / Speaker 0","paragraph":"听力原文","note":"拆解  the end of... ……的结束；part three 第三部分。\n听力提示  正式考官指令，不属于讨论研究。"},{"en":"You now have half a minute to check your answers to part three.","zh":"现在你有半分钟检查第三部分的答案。","speaker":"考官 / Speaker 0","paragraph":"听力原文","note":"拆解  half a minute 半分钟；have time to do 有时间做；check your answers 检查答案。\n听力提示  检查时重点复核转折、数量词和研究结论对应关系。"}],"questions":[],"examples":[]};
